 geography:'🗺️',civics:'⚖️',visual:'🎨',music:'🎵',
 performing:'🎭',computing:'💻',technology:'🛠️',health:'🥗',
 pe:'🏃',home:'🏡',scout:'🧭',guidance:'💡',local:'🗣️'
