const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderSubjectChallenge(u){
 const c=subjectChallenges[u.subject];
 const icon=subjectIcons[u.subject]||'🧪';
 return `<details class="subject-challenge" aria-label="跨單元素養挑戰"><summary><span class="challenge-icon" aria-hidden="true">${icon}</span> 本科跨單元核心探究：${esc(c.title)}</summary><div class="challenge-body"><p class="subtle"><span class="badge-mini">素養探究</span> 這是本科跨單元綜合練習，重在知識遷移與連結；不作為本課死記死背之指標。</p><div class="challenge-scenario-card"><strong class="scenario-label">📌 探究情境：</strong>${esc(c.scenario)}</div><h4 class="challenge-question">❓ 核心問題：${esc(c.question)}</h4><details class="challenge-steps-detail"><summary>💡 逐步提示導引（點擊展開提示）</summary><ol class="challenge-steps-list">${c.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details><details class="challenge-answer-detail"><summary>🔍 核對推理與限制（先推導再看）</summary><div class="challenge-answer-box"><p>${esc(c.answer)}</p></div></details><div class="challenge-transfer-box"><span class="transfer-badge">🚀 條件遷移思辨</span><p><strong>改變一個條件：</strong>${esc(c.transfer)}</p></div></div></details>`;
}
